(4395889, 633954, 22390, '<td valign="top">Very nice building and light. Not easy to make a very good composition because of the modern building on the left and the cars on the right.</td>', 'Very nice building and light. Not easy to make a very good composition because of the modern building on the left and the cars on the right.', '2008-01-16 05:29:17.000000', NULL, 1),
(4395891, 633662, 22390, '<td valign="top">Amazing place and great photo. Nice sky, nice light and very good composition.</td>', 'Amazing place and great photo. Nice sky, nice light and very good composition.', '2008-01-16 05:36:11.000000', NULL, 1),
(4395894, 631671, 22390, '<td valign="top">Nice light. I love the shadow of the chair on the wall.</td>', 'Nice light. I love the shadow of the chair on the wall.', '2008-01-16 05:43:11.000000', NULL, 1),
(4395904, 633025, 71526, '<td valign="top">I like the tree and the railing as a natural frame.</td>', 'I like the tree and the railing as a natural frame.', '2008-01-16 05:54:36.000000', NULL, 1),
(4395905, 633559, 71526, '<td valign="top">I love the high contrast of the sky and the dead trees, dead building.</td>', 'I love the high contrast of the sky and the dead trees, dead building.', '2008-01-16 05:55:51.000000', NULL, 1),
(4395908, 631784, 71526, '<td valign="top">Good concept of abandoned building And car.</td>', 'Good concept of abandoned building And car.', '2008-01-16 05:58:47.000000', NULL, 1),
(4395911, 633662, 71526, '<td valign="top">I like it but here (IMHO) i find the water on the bottom part a bit distracting, perhaps a 2:1 pano would be more effective.</td>', 'I like it but here (IMHO) i find the water on the bottom part a bit distracting, perhaps a 2:1 pano would be more effective.', '2008-01-16 06:00:42.000000', NULL, 1),
