(4395913, 633108, 71526, '<td valign="top">I like your angle here. Good work.</td>', 'I like your angle here. Good work.', '2008-01-16 06:04:31.000000', NULL, 1),
(4395918, 633149, 71526, '<td valign="top">Great composition and B/W!</td>', 'Great composition and B/W!', '2008-01-16 06:07:43.000000', NULL, 1),
(4395921, 632401, 71526, '<td valign="top">ok, a not human building is still a building! :)<br/> <br/>DoF too short for me in this shot.</td>', 'ok, a not human building is still a building! :) DoF too short for me in this shot.', '2008-01-16 06:09:46.000000', NULL, 1),
(4395924, 633685, 71526, '<td valign="top">horizon line is not ok... and perhaps there is too much sky for my taste here, more water will make a more dramatic effect (IMHO). Great idea!</td>', 'horizon line is not ok... and perhaps there is too much sky for my taste here, more water will make a more dramatic effect (IMHO). Great idea!', '2008-01-16 06:11:08.000000', NULL, 1),
(4395929, 632342, 88808, '<td valign="top">Great photo! The Away sign just makes it.</td>', 'Great photo! The Away sign just makes it.', '2008-01-16 06:11:59.000000', NULL, 1),
(4395930, 632225, 71526, '<td valign="top">I like your concept and title. Good work!</td>', 'I like your concept and title. Good work!', '2008-01-16 06:12:03.000000', NULL, 1),
(4395937, 633632, 71526, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=163945" rel="nofollow" target="_blank">Grain Elevator #2 - R.I.P. since 1996</a> got you a red, probably you will get another winner with this amazing shot.</td>', 'Grain Elevator #2 - R.I.P. since 1996 got you a red, probably you will get another winner with this amazing shot.', '2008-01-16 06:16:43.000000', NULL, 1),
(4395939, 631526, 82890, '<td valign="top">Great effects with the snow over the cinderblocks, though I wish the sky was a touch bluer.</td>', 'Great effects with the snow over the cinderblocks, though I wish the sky was a touch bluer.', '2008-01-16 06:17:38.000000', NULL, 1),
(4395941, 632919, 82890, '<td valign="top">The color on this shot is amazing!</td>', 'The color on this shot is amazing!', '2008-01-16 06:18:20.000000', NULL, 1),
(4395951, 633416, 82890, '<td valign="top">This one''s not abandoned! That cat looks right at home! That sign is perfect, though I wish the texture of the bricks came out a bit more, I think it would have added some to the abandoned feel. Great shot!</td>', 'This one''s not abandoned! That cat looks right at home! That sign is perfect, though I wish the texture of the bricks came out a bit more, I think it would have added some to the abandoned feel. Great shot!', '2008-01-16 06:22:57.000000', NULL, 1),
(4395955, 633633, 82890, '<td valign="top">Do you suppose they live in a barn!? Nice use of colors.</td>', 'Do you suppose they live in a barn!? Nice use of colors.', '2008-01-16 06:24:02.000000', NULL, 1),
(4395956, 633322, 82890, '<td valign="top">I love the lighting effects.</td>', 'I love the lighting effects.', '2008-01-16 06:24:50.000000', NULL, 1),
(4395957, 631750, 82890, '<td valign="top">Superb. Nothing I would change, save perhaps who could take credit for it!</td>', 'Superb. Nothing I would change, save perhaps who could take credit for it!', '2008-01-16 06:25:34.000000', NULL, 1),
(4395968, 633220, 51793, '<td valign="top">I like how you can just about see the whole room. Very good take on this challenge. Good luck</td>', 'I like how you can just about see the whole room. Very good take on this challenge. Good luck', '2008-01-16 06:27:50.000000', NULL, 1),
(4395969, 632148, 82890, '<td valign="top">What is the toxic green leaking down from above? I sure hope it''s just a mis-step with your levels, because otherwise the Hudson must be getting dirtier than even when I lived there!</td>', 'What is the toxic green leaking down from above? I sure hope it''s just a mis-step with your levels, because otherwise the Hudson must be getting dirtier than even when I lived there!', '2008-01-16 06:27:50.000000', NULL, 1),
(4395970, 632683, 51793, '<td valign="top">They look like they are what''s left of a an old ghost town</td>', 'They look like they are what''s left of a an old ghost town', '2008-01-16 06:28:11.000000', NULL, 1),
(4395977, 633617, 51793, '<td valign="top">That''s not a building???</td>', 'That''s not a building???', '2008-01-16 06:32:11.000000', NULL, 1),
(4395978, 633025, 51793, '<td valign="top">yeah that looks a little creepy, I wouldn''t have got any closer either. haha</td>', 'yeah that looks a little creepy, I wouldn''t have got any closer either. haha', '2008-01-16 06:32:37.000000', NULL, 1),
(4395980, 633204, 51793, '<td valign="top">Oh this is a good photo. I''m thinking that a B&amp;W would have REALLY set this image off. Good luck with the challenge</td>', 'Oh this is a good photo. I''m thinking that a B&W would have REALLY set this image off. Good luck with the challenge', '2008-01-16 06:33:28.000000', NULL, 1),
