(4395983, 633644, 51793, '<td valign="top">well I see who will be in the top 10. Great job....</td>', 'well I see who will be in the top 10. Great job....', '2008-01-16 06:34:48.000000', NULL, 1),
(4395993, 631671, 88498, '<td valign="top">Excellent - I really like the sense of abandonment.</td>', 'Excellent - I really like the sense of abandonment.', '2008-01-16 06:39:53.000000', NULL, 1),
