(4396016, 632148, 51793, '<td valign="top">This is a great old dorr but I would have liked to see the rest of the building.</td>', 'This is a great old dorr but I would have liked to see the rest of the building.', '2008-01-16 06:56:40.000000', NULL, 1),
(4396023, 632505, 51793, '<td valign="top">This looks kinda like an old school with the concrete around the windows. I like the idea but the branches are just in the way. <br/> <br/>Good luck</td>', 'This looks kinda like an old school with the concrete around the windows. I like the idea but the branches are just in the way.  Good luck', '2008-01-16 06:59:05.000000', NULL, 1),
(4396024, 632205, 51793, '<td valign="top">This is a wonderful ida but the shadows really over power the image. It would have been nice to see more details in the actualy building.</td>', 'This is a wonderful ida but the shadows really over power the image. It would have been nice to see more details in the actualy building.', '2008-01-16 07:02:48.000000', NULL, 1),
(4396026, 632401, 68514, '<td valign="top">7 for originality</td>', '7 for originality', '2008-01-16 07:04:35.000000', NULL, 1),
(4396027, 633780, 51793, '<td valign="top">This is a great building but the vignette is way too powerful for the image.</td>', 'This is a great building but the vignette is way too powerful for the image.', '2008-01-16 07:05:00.000000', NULL, 1),
(4396052, 633168, 69776, '<td valign="top">Just toooo much sharpening for my tastes</td>', 'Just toooo much sharpening for my tastes', '2008-01-16 07:16:11.000000', NULL, 1),
(4396105, 633582, 74979, '<td valign="top">beautiful tones to this image and I like the composition very much..the sky is intense and totally compliments the subject &amp; its poignancy</td>', 'beautiful tones to this image and I like the composition very much..the sky is intense and totally compliments the subject & its poignancy', '2008-01-16 07:53:15.000000', NULL, 1),
