(4400092, 633587, 80904, '<td valign="top">I see so much potential for this one if it were cropped right so that the house wasnt centered and then converted into black and white by manipulating the blues to be darker and reds and yellows lighter. It would be very dramatic.</td>', 'I see so much potential for this one if it were cropped right so that the house wasnt centered and then converted into black and white by manipulating the blues to be darker and reds and yellows lighter. It would be very dramatic.', '2008-01-17 13:48:25.000000', NULL, 1),
(4400100, 633334, 80904, '<td valign="top">I think I know what you were trying to accomplish, but I think the camera was too far from the stripe. The stripe instead of serving as a frame, it distracts IMHO</td>', 'I think I know what you were trying to accomplish, but I think the camera was too far from the stripe. The stripe instead of serving as a frame, it distracts IMHO', '2008-01-17 13:51:21.000000', NULL, 1),
(4400102, 633080, 80904, '<td valign="top">Good time of the day that you took this shot. Unfortunately too many trees, its a bit cluttered</td>', 'Good time of the day that you took this shot. Unfortunately too many trees, its a bit cluttered', '2008-01-17 13:52:06.000000', NULL, 1),
(4400109, 632554, 80904, '<td valign="top">Great framing. I cant keep my eyes off the green. Good job</td>', 'Great framing. I cant keep my eyes off the green. Good job', '2008-01-17 13:53:52.000000', NULL, 1),
(4400114, 631719, 75733, '<td valign="top">I wish I could see more of the building.  Maybe a different crop...</td>', 'I wish I could see more of the building.  Maybe a different crop...', '2008-01-17 13:54:56.000000', NULL, 1),
(4400117, 632686, 80904, '<td valign="top">This shot is too cluttered with trees. I know abandon houses tend to be, but the frame only of the house is hidden in the trees. perhaps thats what you wanted though.</td>', 'This shot is too cluttered with trees. I know abandon houses tend to be, but the frame only of the house is hidden in the trees. perhaps thats what you wanted though.', '2008-01-17 13:55:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4400119, 633550, 80904, '<td valign="top">This almost looks like Alcatraz from the inside. Good job</td>', 'This almost looks like Alcatraz from the inside. Good job', '2008-01-17 13:55:35.000000', NULL, 1),
(4400122, 633090, 80904, '<td valign="top">Nice framing The branches in the way kinda bites, but its a good shot nonetheless.</td>', 'Nice framing The branches in the way kinda bites, but its a good shot nonetheless.', '2008-01-17 13:56:02.000000', NULL, 1),
(4400131, 632042, 75733, '<td valign="top">The building is uneven in the frame and the blue sky on either side does nothing for me.  I also don''t like how the bottom is cropped out. It looks like nothing is gounding it.  It''s a cool building but maybe another angle or different crop would make it work better.</td>', 'The building is uneven in the frame and the blue sky on either side does nothing for me.  I also don''t like how the bottom is cropped out. It looks like nothing is gounding it.  It''s a cool building but maybe another angle or different crop would make it work better.', '2008-01-17 13:58:36.000000', NULL, 1),
(4400138, 632000, 75733, '<td valign="top">I love this building; it has a lot of character and the colors are neat.  I think this image is a tad flat, I would try to increase contrast and play with the levels (my opinion!)</td>', 'I love this building; it has a lot of character and the colors are neat.  I think this image is a tad flat, I would try to increase contrast and play with the levels (my opinion!)', '2008-01-17 14:00:39.000000', NULL, 1),
