(4400156, 632463, 75733, '<td valign="top">Beautiful image!  I love that the two walls lead your eye to the center building, yet it''s off center in the image.  I also love the light over the wall on the left.  Very pleasing!! Great job!</td>', 'Beautiful image!  I love that the two walls lead your eye to the center building, yet it''s off center in the image.  I also love the light over the wall on the left.  Very pleasing!! Great job!', '2008-01-17 14:06:36.000000', NULL, 1),
(4400160, 632822, 45377, '<td valign="top">I like the colours &amp; textures within the shot. A fairly common composition.</td>', 'I like the colours & textures within the shot. A fairly common composition.', '2008-01-17 14:07:36.000000', NULL, 1),
(4400168, 631369, 45377, '<td valign="top">Good abstract composition. Strong contrasting colour. Good effort</td>', 'Good abstract composition. Strong contrasting colour. Good effort', '2008-01-17 14:10:31.000000', NULL, 1),
(4400169, 633645, 43774, '<td valign="top">It''s cool how the black area actually looks like a figure entering the window.</td>', 'It''s cool how the black area actually looks like a figure entering the window.', '2008-01-17 14:10:42.000000', NULL, 1),
(4400170, 633470, 43774, '<td valign="top">Looks like it was beautiful in its day. Love the trees to the right.</td>', 'Looks like it was beautiful in its day. Love the trees to the right.', '2008-01-17 14:11:02.000000', NULL, 1),
