(4403066, 631238, 80904, '<td valign="top">I like it, specially that I can read that closed sign :)</td>', 'I like it, specially that I can read that closed sign :)', '2008-01-18 15:50:02.000000', NULL, 1),
(4403067, 632293, 80904, '<td valign="top">Nice grafitti. Nice for photoshoots :)</td>', 'Nice grafitti. Nice for photoshoots :)', '2008-01-18 15:50:23.000000', NULL, 1),
(4403071, 633421, 80904, '<td valign="top">Interesting textures. :)</td>', 'Interesting textures. :)', '2008-01-18 15:52:58.000000', NULL, 1),
