(4409221, 632401, 80908, '<td valign="top">OOBIE! Clever. Nicely shot too although I might have moved the light a little further to the front to catch part of the entrance, but now I am being picky!</td>', 'OOBIE! Clever. Nicely shot too although I might have moved the light a little further to the front to catch part of the entrance, but now I am being picky!', '2008-01-21 06:40:41.000000', NULL, 1),
(4409451, 633018, 70875, '<td valign="top">The sky is too bright. You need to reshoot at another time of day when the light want be so harsh.</td>', 'The sky is too bright. You need to reshoot at another time of day when the light want be so harsh.', '2008-01-21 08:45:34.000000', NULL, 1),
(4409952, 633848, 39679, '<td valign="top">Wow...the sky is amazing (polarizers are you''re friend).  Personally I''d like to see less density (more detail) on the building.  That said, with strong lighting like this, I know that''s really hard to manage.  <br/> <br/>Still an excellent shot.</td>', 'Wow...the sky is amazing (polarizers are you''re friend).  Personally I''d like to see less density (more detail) on the building.  That said, with strong lighting like this, I know that''s really hard to manage.   Still an excellent shot.', '2008-01-21 11:07:33.000000', NULL, 1),
(4409980, 632205, 86799, '<td valign="top">Needs more contrasting detail.  The fallen down portion seems to be lost in the "still standing" portion.</td>', 'Needs more contrasting detail.  The fallen down portion seems to be lost in the "still standing" portion.', '2008-01-21 11:23:07.000000', NULL, 1),
(4409992, 633658, 86799, '<td valign="top">Interesting positioning and angle of view.  The foreground overgrowth really adds to the abandonment flavor.  Good work, I think.</td>', 'Interesting positioning and angle of view.  The foreground overgrowth really adds to the abandonment flavor.  Good work, I think.', '2008-01-21 11:26:21.000000', NULL, 1),
