(4410011, 633451, 86799, '<td valign="top">Excellent.  The angle accentuates the height of the weeds perfectly.  Great color and quality.  Love the title.</td>', 'Excellent.  The angle accentuates the height of the weeds perfectly.  Great color and quality.  Love the title.', '2008-01-21 11:31:01.000000', NULL, 1),
(4410030, 633322, 86799, '<td valign="top">New construction.  Abandoned?  not sure this meets challenge...</td>', 'New construction.  Abandoned?  not sure this meets challenge...', '2008-01-21 11:34:25.000000', NULL, 1),
