(4410234, 633712, 73661, '<td valign="top">Oooh it''s creepy but I like it! 10!</td>', 'Oooh it''s creepy but I like it! 10!', '2008-01-21 12:23:47.000000', NULL, 1),
(4410491, 632919, 45377, '<td valign="top">Great colours &amp; tones. Interesting composition, really draws your eye all the way to the top of the frame. I would be interested to know what post processing was done. Good work.</td>', 'Great colours & tones. Interesting composition, really draws your eye all the way to the top of the frame. I would be interested to know what post processing was done. Good work.', '2008-01-21 13:21:59.000000', NULL, 1),
(4410492, 633206, 45377, '<td valign="top">I love the composition of this photo. I could see it as a movie poster for a horror film.</td>', 'I love the composition of this photo. I could see it as a movie poster for a horror film.', '2008-01-21 13:22:16.000000', NULL, 1),
(4410494, 633712, 45377, '<td valign="top">Well composed. Good B&amp;W. The only thing that lets it down for me is that the roof of the house blends into the sky. Good effort</td>', 'Well composed. Good B&W. The only thing that lets it down for me is that the roof of the house blends into the sky. Good effort', '2008-01-21 13:22:33.000000', NULL, 1),
(4410497, 633810, 45377, '<td valign="top">Great shot. Reminded me of the cover of Led Zeppelin''s album, Physical Graffiti. I like the texture in the brickwork. Would also look good if just the  stair cases filled the frame.</td>', 'Great shot. Reminded me of the cover of Led Zeppelin''s album, Physical Graffiti. I like the texture in the brickwork. Would also look good if just the  stair cases filled the frame.', '2008-01-21 13:22:39.000000', NULL, 1),
(4410500, 633875, 45377, '<td valign="top">Great B&amp;W. The dramatic sky really adds to this photo. Perhaps framed a bit tight? Good work.</td>', 'Great B&W. The dramatic sky really adds to this photo. Perhaps framed a bit tight? Good work.', '2008-01-21 13:23:16.000000', NULL, 1),
(4410502, 631238, 45377, '<td valign="top">Well framed. Has a creepy feel to it</td>', 'Well framed. Has a creepy feel to it', '2008-01-21 13:23:29.000000', NULL, 1),
(4410683, 633019, 86191, '<td valign="top">I really like the "light at the end of the tunnel" effect but the image is a little to dark.  The graffiti on the wall adds color and contrast! You have a great angle and picture!</td>', 'I really like the "light at the end of the tunnel" effect but the image is a little to dark.  The graffiti on the wall adds color and contrast! You have a great angle and picture!', '2008-01-21 13:58:30.000000', NULL, 1),
