(4410805, 633290, 44611, '<td valign="top">Interesting entry.. good composition, although it would have been even better if the cattle had looked up at you.  I like the colours - bright and yet not over saturated, but I''m sorry I do not like the frame at all.</td>', 'Interesting entry.. good composition, although it would have been even better if the cattle had looked up at you.  I like the colours - bright and yet not over saturated, but I''m sorry I do not like the frame at all.', '2008-01-21 14:33:50.000000', NULL, 1),
(4410806, 632919, 44611, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2008-01-21 14:34:10.000000', NULL, 1),
